fn save::(path, obj) {
    @write(path, @json_encode(obj));
    return true;
}

fn load::(path) {
    if (!@exists(path)) { return null; }
    return @json_decode(@read(path));
}

fn save_lines::(path, lines) {
    @write(path, @join(lines, "\n"));
    return true;
}

fn load_lines::(path) {
    if (!@exists(path)) { return []; }
    return @split(@read(path), "\n");
}

fn save_ini::(path, m) {
    let out = [];
    for k in @keys(m) {
        @push(out, @str(k) + "=" + @str(m[k]));
    }
    @write(path, @join(out, "\n"));
    return true;
}

fn load_ini::(path) {
    let lines = load_lines(path);
    let m = {};
    for line in lines {
        let trimmed = line;
        let eq = -1;
        let i = 0;
        while (i < @len(trimmed)) {
            if (@substr(trimmed, i, 1) == "=") {
                eq = i;
                break;
            }
            i = i + 1;
        }
        if (eq >= 0) {
            let k = @substr(trimmed, 0, eq);
            let v = @substr(trimmed, eq + 1);
            m[k] = v;
        }
    }
    return m;
}

fn config_get::(path, key, default) {
    let m = load_ini(path);
    if (@has(m, key)) { return m[key]; }
    return default;
}

fn config_set::(path, key, value) {
    let m = load_ini(path);
    m[key] = value;
    return save_ini(path, m);
}

fn append_line::(path, line) {
    @append(path, line + "\n");
    return true;
}
